UPDATE UNIT_RESIDENT
SET MOVE_IN_DT = #{moveInDt},
    MOVE_OUT_DT = #{moveOutDt}
WHERE UNIT_ID = #{unitId}
  AND BLDG_ID = #{bldgId}
  AND RENTAL_PTY_ID = #{rentalPtyId}
  AND MBR_CD = #{mbrCd}

UPDATE UNIT_RESIDENT
SET UNIT_DEL_YN = 'Y'
WHERE UNIT_ID = #{unitId}
  AND BLDG_ID = #{bldgId}
  AND RENTAL_PTY_ID = #{rentalPtyId}
  AND MBR_CD = #{mbrCd}

UPDATE UNIT
   SET MBR_CD = 'master'
 WHERE UNIT_ID = #{unitId}
   AND BLDG_ID = #{bldgId}
   AND RENTAL_PTY_ID = #{rentalPtyId}

UPDATE UNIT_RESIDENT
   SET UNIT_DEL_YN = 'N',
       MOVE_IN_DT = #{moveInDt}
 WHERE UNIT_ID = #{unitId}
   AND BLDG_ID = #{bldgId}
   AND RENTAL_PTY_ID = #{rentalPtyId}
   AND MBR_CD = #{mbrCd}
   AND UNIT_DEL_YN = 'Y'
